      '有人對主人說：「要是早聽客人的話，就不用花牛和酒，也不會失火。現在論功請客，提醒改煙囪的人沒有功勞，燒得焦頭爛額的人反倒成了上賓嗎？」主人這才醒悟，把客人請來。',
