    original: '臣聞客有過主人者，見其竈直突，傍有積薪，客謂主人，更爲曲突，遠徙其薪，不者且有火患。主人默然不應。俄而家果失火，鄰里共救之，幸而得息。於是殺牛置酒，謝其鄰人，灼爛者在於上行，餘各以功次坐，而不錄言曲突者。人謂主人曰：『鄉使聽客之言，不費牛酒，終亡火患。今論功而請賔，曲突徙薪亡恩澤，燋頭爛額爲上客耶？』主人迺寤而請之。',
