    panels: [
      '諸葛亮為劉備分析完天下大勢，劉備說：「好！」',
      '從此劉備和諸葛亮的情誼一天比一天親密。',
      '關羽、張飛等人很不高興。',
      '劉備勸他們：「我有了孔明，就像魚有了水，希望各位不要再說了。」關羽、張飛才不再抱怨。',
    ],
    original: '先主曰：『善！』於是與亮情好日密。關羽、張飛等不悅，先主解之曰：『孤之有孔明，猶魚之有水也。願諸君勿復言。』羽、飛乃止。',
