    example: '他轉到美術班以後如魚得水，每天都畫得很開心。',
    situation: '小琪加入天文社後，遇到一群和她一樣愛看星星的同學，社課從來不缺席。',
    note: '「先主」是陳壽對劉備的稱呼，「善」是好，「情好日密」是感情一天比一天親密，「不悅」是不高興，「解之」是向他們解釋、勸解，「孤」是劉備自稱，「孔明」是諸葛亮的字，「諸君」是各位，「勿復言」是不要再說，「乃止」是才停止。〈關羽傳〉寫「羽美鬚髯」，漫畫只照原文畫長鬍鬚；常見的紅臉、大刀是後來小說《三國演義》裡的形象，漫畫不畫。這段接在劉備三次拜訪諸葛亮之後(見「三顧茅廬」漫畫)。',
