    note: '「太宗」就是明成祖(他死後的廟號本來是太宗，嘉靖年間改為成祖)，「楷書」是端正的字體，「典籍」是官名，「豐潤」是飽滿圓潤，「上」是皇帝，「大制作」是重要的文書，「謄冩」是抄寫(「冩」同「寫」)，「累遷」是一路升官，「學士」是官名，「俸」是薪水，「仍事書辦」是工作仍是書寫，「象笏」是象牙做的笏板(大臣上朝時拿在手上的長板)，「鏤金刻度姓名其上」是在上面用金刻上沈度的名字，「寵耀」是讓他光榮，「粲」是沈度的弟弟沈粲，「侍讀」是官名，「盛行於朝」是在朝廷很流行，「為式」是當作範本，「宣宗」是明宣宗，「冲齡」是年紀很小(「冲」同「沖」)，「古法帖」是古代書法家的字帖，「宸翰」是皇帝親筆寫的字，「妙絶」是好極了(「絶」同「絕」)，「趙孟頫」是元朝的書法家(「頫」念ㄈㄨˇ)，「遒勁」是剛強有力(「遒」念ㄑㄧㄡˊ)，「精能之至」是精熟到了極點，「出神入化」是神妙得像進入了化境。原文特別說皇帝練字還沒拿沈度的字當範本：明宣宗學的是古代的字帖，先學趙孟頫，不是跟沈度學。《明史‧沈度傳》說沈度和弟弟沈粲都得到刻名字的象牙笏；這裡照《翰林記》只寫沈度。',
